#!/usr/bin/env python3
"""
This program uses backtracking to solve the 6‐house Zebra logic puzzle.
It assigns six attributes – Name, Lunch, Height, Favorite drink, Type of pet, and Phone model –
to houses 1 through 6 while enforcing all given puzzle constraints.
When a complete solution is found, it is output as a JSON-formatted dictionary.
"""

import json
import sys

# The complete set of possible values for each attribute
NAMES = ["Arnold", "Bob", "Peter", "Alice", "Carol", "Eric"]
LUNCHES = ["stew", "grilled cheese", "stir fry", "soup", "pizza", "spaghetti"]
HEIGHTS = ["tall", "average", "super tall", "very short", "very tall", "short"]
DRINKS = ["root beer", "boba tea", "coffee", "water", "tea", "milk"]
PETS = ["hamster", "fish", "cat", "dog", "bird", "rabbit"]
PHONES = ["samsung galaxy s21", "xiaomi mi 11", "google pixel 6", "iphone 13", "huawei p50", "oneplus 9"]

NUM_HOUSES = 6

# We'll represent each house as a dictionary with keys:
# "House", "Name", "Lunch", "Height", "Favorite drink", "Type of pet", "Phone model"

def ordering_constraints(houses):
    """
    Check ordering constraints among houses that are already assigned.
    Houses is a list of length NUM_HOUSES; some entries may still be None.
    We check these constraints only when both involved houses are assigned.
    """
    assigned = [(i, h) for i, h in enumerate(houses) if h is not None]
    # Constraint: The person who loves soup is in the second house.
    # (This is enforced in candidate generation for house2.)
    # Constraint: The boba tea drinker must be somewhere to the right of the soup house.
    soup_index = None
    for i, h in assigned:
        if h["Lunch"] == "soup":
            soup_index = i
            break
    if soup_index is not None:
        for i, h in assigned:
            if h["Favorite drink"] == "boba tea" and i <= soup_index:
                return False

    # Constraint: The person with name "Peter" must be to the right of the person "Alice".
    idx_alice = None
    idx_peter = None
    for i, h in assigned:
        if h["Name"] == "Alice":
            idx_alice = i
        if h["Name"] == "Peter":
            idx_peter = i
    if idx_alice is not None and idx_peter is not None:
        if idx_alice >= idx_peter:
            return False

    # Constraint: The person who uses google pixel 6 (spaghetti person)
    # must be to the left of the person who owns a hamster.
    idx_pixel6 = None
    idx_hamster = None
    for i, h in assigned:
        if h["Phone model"] == "google pixel 6":
            idx_pixel6 = i
        if h["Type of pet"] == "hamster":
            idx_hamster = i
    if idx_pixel6 is not None and idx_hamster is not None:
        if idx_pixel6 >= idx_hamster:
            return False

    # Constraint: The person with a pet bird is somewhere to the left of the person who loves spaghetti.
    idx_bird = None
    idx_spaghetti = None
    for i, h in assigned:
        if h["Type of pet"] == "bird":
            idx_bird = i
        if h["Lunch"] == "spaghetti":
            idx_spaghetti = i
    if idx_bird is not None and idx_spaghetti is not None:
        if idx_bird >= idx_spaghetti:
            return False

    return True

def neighbor_constraints(prev, candidate):
    """
    Check constraints linking the previous house (prev) and the candidate for the current house.
    These constraints are applied if the neighbor (prev) is assigned.
    """
    # If the previous house's favorite drink is "root beer", then the current house's phone must be "xiaomi mi 11".
    if prev.get("Favorite drink") == "root beer":
        if candidate.get("Phone model") is not None and candidate["Phone model"] != "xiaomi mi 11":
            return False
    # If the previous house's phone is "huawei p50", then the current house's lunch must be "grilled cheese".
    if prev.get("Phone model") == "huawei p50":
        if candidate.get("Lunch") is not None and candidate["Lunch"] != "grilled cheese":
            return False
    # If the previous house's favorite drink is "tea", then the current house's lunch must be "pizza".
    if prev.get("Favorite drink") == "tea":
        if candidate.get("Lunch") is not None and candidate["Lunch"] != "pizza":
            return False
    # If the previous house's name is "Alice", then the current house's name must be "Eric".
    if prev.get("Name") == "Alice":
        if candidate.get("Name") is not None and candidate["Name"] != "Eric":
            return False
    return True

def self_constraints(candidate, house_index):
    """
    Check constraints that involve only the candidate (for a single house).
    house_index is 0-based.
    """
    # Fixed house positions:
    if house_index == 1:  # House 2 must have lunch "soup"
        if candidate.get("Lunch") != "soup":
            return False
    if house_index == 2:  # House 3 must use "iphone 13"
        if candidate.get("Phone model") != "iphone 13":
            return False

    # Constraint: A house with height "very tall" is not in the second house.
    if candidate.get("Height") == "very tall" and house_index == 1:
        return False

    # Person-specific constraints:
    if candidate.get("Name") == "Bob":
        # Bob is tall and loves grilled cheese.
        if candidate.get("Height") != "tall" or candidate.get("Lunch") != "grilled cheese":
            return False
    if candidate.get("Name") == "Arnold":
        # Arnold is very tall and uses oneplus 9.
        if candidate.get("Height") != "very tall" or candidate.get("Phone model") != "oneplus 9":
            return False
    if candidate.get("Name") == "Carol":
        # Carol uses samsung galaxy s21.
        if candidate.get("Phone model") != "samsung galaxy s21":
            return False
    if candidate.get("Name") == "Alice":
        # Alice is super tall and has pet fish.
        if candidate.get("Height") != "super tall" or candidate.get("Type of pet") != "fish":
            return False

    # Lunch-to-other mappings:
    if candidate.get("Lunch") == "spaghetti":
        # Spaghetti lover must be very short and use google pixel 6.
        if candidate.get("Height") != "very short" or candidate.get("Phone model") != "google pixel 6":
            return False
    if candidate.get("Lunch") == "pizza":
        # Pizza lover must be short.
        if candidate.get("Height") != "short":
            return False
    if candidate.get("Lunch") == "stir fry":
        # Stir fry person must drink milk and have pet dog.
        if candidate.get("Favorite drink") != "milk" or candidate.get("Type of pet") != "dog":
            return False

    # Phone-to-drink mapping:
    if candidate.get("Phone model") == "xiaomi mi 11":
        if candidate.get("Favorite drink") != "coffee":
            return False

    # Non-adjacency (house 5 restrictions): House 5 means index 4.
    if house_index == 4:
        if candidate.get("Type of pet") in ["hamster", "rabbit"]:
            return False

    return True

def backtrack(houses, used, house_index):
    if house_index == NUM_HOUSES:
        # All houses assigned: final check of ordering constraints.
        if ordering_constraints(houses):
            return houses
        else:
            return None

    # For each attribute, select the values not already used.
    possible_names = [n for n in NAMES if n not in used["Name"]]
    possible_lunches = [l for l in LUNCHES if l not in used["Lunch"]]
    possible_heights = [h for h in HEIGHTS if h not in used["Height"]]
    possible_drinks = [d for d in DRINKS if d not in used["Favorite drink"]]
    possible_pets = [p for p in PETS if p not in used["Type of pet"]]
    possible_phones = [ph for ph in PHONES if ph not in used["Phone model"]]

    # Iterate over the Cartesian product of possible values.
    for name in possible_names:
        for lunch in possible_lunches:
            for height in possible_heights:
                for drink in possible_drinks:
                    for pet in possible_pets:
                        for phone in possible_phones:
                            candidate = {
                                "House": str(house_index + 1),
                                "Name": name,
                                "Lunch": lunch,
                                "Height": height,
                                "Favorite drink": drink,
                                "Type of pet": pet,
                                "Phone model": phone
                            }
                            # First, check constraints that involve only this candidate.
                            if not self_constraints(candidate, house_index):
                                continue

                            # If this is not the first house, check neighbor constraints with the previous house.
                            if house_index > 0:
                                prev = houses[house_index - 1]
                                if prev is not None:
                                    if not neighbor_constraints(prev, candidate):
                                        continue

                            # Temporarily assign candidate to house_index.
                            houses[house_index] = candidate
                            # Mark the used values.
                            used["Name"].add(name)
                            used["Lunch"].add(lunch)
                            used["Height"].add(height)
                            used["Favorite drink"].add(drink)
                            used["Type of pet"].add(pet)
                            used["Phone model"].add(phone)

                            # Check ordering constraints among houses assigned so far.
                            if not ordering_constraints(houses):
                                # Roll back assignment.
                                used["Name"].remove(name)
                                used["Lunch"].remove(lunch)
                                used["Height"].remove(height)
                                used["Favorite drink"].remove(drink)
                                used["Type of pet"].remove(pet)
                                used["Phone model"].remove(phone)
                                houses[house_index] = None
                                continue

                            # Recurse to the next house.
                            result = backtrack(houses, used, house_index + 1)
                            if result is not None:
                                return result

                            # Backtrack: remove candidate.
                            used["Name"].remove(name)
                            used["Lunch"].remove(lunch)
                            used["Height"].remove(height)
                            used["Favorite drink"].remove(drink)
                            used["Type of pet"].remove(pet)
                            used["Phone model"].remove(phone)
                            houses[house_index] = None
    return None

def solve_puzzle():
    # Initialize houses list and used dictionaries.
    houses = [None] * NUM_HOUSES
    used = {
        "Name": set(),
        "Lunch": set(),
        "Height": set(),
        "Favorite drink": set(),
        "Type of pet": set(),
        "Phone model": set()
    }
    solution = backtrack(houses, used, 0)
    return solution

def main():
    sol = solve_puzzle()
    if sol is None:
        print(json.dumps({"solution": {"header": [], "rows": []}}))
        sys.exit(0)

    # Build output dictionary in required format.
    header = ["House", "Name", "Lunch", "Height", "Favorite drink", "Type of pet", "Phone model"]
    rows = []
    # Order the houses by house number (already in order 1 to 6)
    for house in sol:
        row = [house["House"], house["Name"], house["Lunch"], house["Height"], house["Favorite drink"], house["Type of pet"], house["Phone model"]]
        rows.append(row)
    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()
